# otel_probe.py: generated by otel-as-code v{{VERSION}} (/otel-why). Temporary timing spans for one
# investigation, not part of the baseline. Remove every probe and this file with
# /otel-uninstrument --probes.
import inspect
import time

from opentelemetry import trace

# The tracer name is the marker: trace_summary.py reports these spans as probes.
_tracer = trace.get_tracer("otel-as-code.probe")


def probe(name, fn, *args, **kwargs):
    """Run fn(*args, **kwargs) inside a span called `name` and return its result. A coroutine
    function returns an awaitable. The span records the thread CPU time used while it was open, so
    the summary can show computing next to waiting; on an event loop that includes other tasks."""
    if inspect.iscoroutinefunction(fn):
        return _probe_async(name, fn, *args, **kwargs)
    with _tracer.start_as_current_span(name) as span:
        cpu_start = time.thread_time()
        try:
            return fn(*args, **kwargs)
        finally:
            span.set_attribute("otel_as_code.probe.cpu_ms", (time.thread_time() - cpu_start) * 1000)


async def _probe_async(name, fn, *args, **kwargs):
    with _tracer.start_as_current_span(name) as span:
        cpu_start = time.thread_time()
        try:
            return await fn(*args, **kwargs)
        finally:
            span.set_attribute("otel_as_code.probe.cpu_ms", (time.thread_time() - cpu_start) * 1000)
